  "suggested_treatments": [
    { "kind": "self_care", "description": "실리콘 겔 시트 또는 실리콘 젤을 반흔에 지속 부착(하루 12~24시간, 최소 2~3개월). 시작 시점: 봉합 제거 후 상처가 완전히 닫혔으면 지금부터 시작 가능하다는 것이 일반적 견해.", "basis": "guideline" },
    { "kind": "self_care", "description": "압박 요법: 안면은 귀·일부 부위 외에는 균일한 압박 적용이 어렵다. 안면에는 실리콘 위주로 하고, 압박은 이개(귀) 켈로이드 등 국소에 한정해 시술자 지도 하에 시행.", "basis": "guideline" },
    { "kind": "self_care", "description": "자외선 차단(SPF 30+ 이상, 물리적 차단 병행). 반흔 색소 침착과 융기 악화 예방. 최소 6~12개월.", "basis": "guideline" },
    { "kind": "self_care", "description": "긁기·문지르기·강한 마사지 회피. 자극은 비후 악화 인자.", "basis": "guideline" },
    { "kind": "otc", "description": "일반 보습제로 반흔 부위 건조 방지. 스테로이드 외용제는 안면에서 위축·모세혈관 확장·색소 변화 위험이 있어 자가 사용 권하지 않음 — 의사·약사 확인 필요.", "basis": "guideline" },
    { "kind": "prescription_drug", "description": "병변내 스테로이드 주사(triamcinolone 계열 등): 비후성 반흔·켈로이드 1차 치료 중 하나. 시작 시점은 통상 반흔이 활동성으로 진행(경계 확장 또는 3개월 이후에도 지속 성장·강한 증상) 시 피부과 평가 후 시작. 안면은 위축·색소 저하·모세혈관 확장 위험이 상대적으로 크므로 저용량·간격 조절을 시술자가 결정. 용량은 시술자·약사 확인 필요(본 SP는 용량을 제시하지 않음).", "basis": "guideline" },
    { "kind": "procedure", "description": "레이저(예: pulsed dye laser — 홍반·가려움·융기 조절), 필요시 반흔 재절제 + 보조요법. 모두 시술자 평가 후. 안면은 시술 종류·강도·시기에 따라 색소 변화 위험이 커 개별화 필요.", "basis": "guideline" },
    { "kind": "referral", "description": "피부과(또는 성형외과) 대면 진료 — 감별 확정과 치료 시작 시점 결정을 위해 권장.", "basis": "guideline" }
  ],

